package b.language.server.hover

import com.google.gson.Gson
import de.prob.unicode.UnicodeTranslator

/** A documented keyword or operator; [primary] tells whether [key] names the construct, unlike THEN in IF … THEN … END. */
private data class Entry(
    val key: String,
    val title: String,
    val description: String,
    val link: String,
    val source: String,
    val primary: Boolean,
)

/** Hovers of classical B: the documentation of keywords and operators. */
object ClassicBHover {
    private val WORD = Regex("""[\w']+""")

    /** Generated by `./gradlew generateDocumentation`. */
    private val documentation by lazy {
        val json = javaClass.getResource("/documentation/classical.json")!!.readText()
        Gson().fromJson(json, Array<Entry>::class.java).groupBy { it.key }
    }

    /** The Markdown documenting what is written at ([line], [column]) of [text], if anything. */
    fun hover(text: String, line: Int, column: Int): String? {
        val source = text.lines().getOrNull(line)?.takeIf { column in it.indices } ?: return null
        val word = WORD.findAll(source).firstOrNull { column in it.range }?.value
        val entries = (if (word != null) documentation[word] else operatorAt(source, column)) ?: return null
        return entries.sortedByDescending { it.primary }.distinctBy { it.title }.take(3).joinToString("\n\n---\n\n", transform = ::render)
    }

    /** The entries of the longest operator covering [column], written in ASCII or Unicode. */
    private fun operatorAt(line: String, column: Int): List<Entry>? {
        for (length in 5 downTo 1) {
            for (start in maxOf(0, column - length + 1)..minOf(column, line.length - length)) {
                val operator = line.substring(start, start + length)
                (documentation[operator] ?: documentation[UnicodeTranslator.toAscii(operator).trim()])?.let { return it }
            }
        }
        return null
    }

    private fun render(entry: Entry) =
        "```b\n${entry.title}\n```\n\n${entry.description.replaceFirstChar { it.uppercase() }}\n\n[${entry.source}](${entry.link})"
}
